-- Register risiko memuat Formulir Risiko Keberhasilan SMEn (klausul 6.1, 001/SOP-007/KINRA/SMEn/X/2026) untuk SEMUA 10 bagian,
-- dari folder OneDrive "Formulir Risiko Keberhasilan (KINRA)" (versi 4 Nov 2026, lebih baru dari berkas bernomor 2-3 Nov).
-- Menggantikan isi 0046 (baru Korporasi dan Akuntansi & Keuangan). Baris dari formulir 6.1 yang ada dihapus lalu dimuat ulang,
-- jadi perubahan baris 6.1 lewat aplikasi ikut tertimpa; isu lain (peluang 4.1, isu tambahan manual) tidak disentuh.
-- Baris contoh template (skor ilustratif) tidak diimpor. Proses berjudul "Peluang ..." dicatat sebagai jenis Peluang.
-- Asal Eksternal ditetapkan dari kata kunci proses (tenant/pihak ketiga, pasokan, tarif, hukum/regulasi/kepatuhan, pemasok).
-- Jalankan setelah 0046. Aman diulang.

delete from isu where sumber like 'Formulir Risiko 6.1%';

insert into isu (asal, jenis, bagian, proses, uraian, dampak, kemungkinan, dampak_residual, kemungkinan_residual, signifikan, tindakan, evaluasi, pic, target, sumber)
values
('Internal', 'Risiko', 'Korporasi', 'Tata kelola dan integrasi SMEn korporat', 'Pengelolaan SMEn belum terintegrasi ke perencanaan strategis, KPI, anggaran, keputusan investasi, dan tinjauan kinerja korporat.', 4, 3, 2, 2, true, 'Tetapkan peran, kewenangan, RACI, sasaran, anggaran, agenda tinjauan manajemen dan mekanisme eskalasi; hubungkan dengan rencana korporat.
Tindak lanjut: Rencana kerja tahunan; tinjauan triwulan; tinjauan manajemen tahunan', 'Dokumen rencana kerja dan sasaran energi yang disetujui; notulen tinjauan triwulan; laporan pencapaian target dan EnPI; notulen tinjauan manajemen; daftar keputusan dan tindak lanjut beserta status penyelesaiannya.', 'Direksi/Manajemen Puncak; Koordinator/Tim SMEn; pemilik proses terkait', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Kualitas data konsumsi energi korporat', 'Data tagihan, meter, jam operasi, dan konsumsi fasilitas tidak lengkap, terlambat, berbeda antarunit atau tidak dapat ditelusuri.', 4, 4, 2, 2, true, 'Tetapkan data owner per fasilitas, kontrol kelengkapan dan kewajaran, arsip bukti, pemeriksaan anomali serta penanganan data hilang.
Tindak lanjut: Kontrol awal 1 bulan; evaluasi bulanan', 'Rekapitulasi konsumsi energi bulanan; rekonsiliasi data meter dan tagihan; log pencatatan energi; daftar anomali dan koreksi data; laporan kelengkapan dan ketepatan waktu data; bukti persetujuan data oleh penanggung jawab.', 'Tim SMEn; Keuangan; Operasi/Pengelola Fasilitas; TI bila sistem data digunakan', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Keterbatasan pengukuran/submeter', 'Belum tersedia pengukuran terpisah untuk fasilitas atau penggunaan energi yang konsumsi/peluang perbaikannya penting.', 4, 3, 2, 2, true, 'Susun rencana pengukuran bertahap; verifikasi akurasi meter; tetapkan estimasi sementara yang transparan sampai data tersedia.
Tindak lanjut: Rencana pengukuran dalam 3 bulan; implementasi mengikuti anggaran', 'Peta titik pengukuran energi; daftar meter dan submeter; kajian kebutuhan serta prioritas pengukuran; analisis biaya dan manfaat; rencana anggaran; persetujuan investasi; laporan pemasangan atau verifikasi meter; rekaman hasil pengukuran.', 'Operasi/Pengelola Fasilitas; Tim SMEn; Keuangan; Pengadaan', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Pengendalian operasi gedung dan fasilitas', 'Jam operasi, setelan, kontrol atau pemeliharaan AC, pencahayaan, pompa dan peralatan pendukung tidak sesuai kebutuhan layanan.', 3, 4, 2, 2, true, 'Tentukan batas operasi, set point yang disetujui, checklist inspeksi, pemilik peralatan dan eskalasi penyimpangan.
Tindak lanjut: Pengendalian rutin; evaluasi bulanan', 'SOP pengoperasian dan pemeliharaan fasilitas; checklist inspeksi; log jam operasi peralatan; catatan pemeliharaan; rekapitulasi konsumsi listrik; tren EnPI bulanan; laporan penyimpangan dan bukti tindakan koreksi.', 'Pengelola Gedung/Fasilitas; Operasi; Pemeliharaan; pengguna fasilitas', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Pengadaan tanpa kriteria kinerja energi', 'Spesifikasi dan evaluasi pembelian peralatan/jasa tidak memasukkan efisiensi energi atau biaya siklus hidup ketika relevan.', 4, 3, 2, 2, true, 'Tentukan kategori pengadaan yang wajib ditinjau Tim SMEn/teknis; dokumentasikan alasan bila kriteria tidak dapat diterapkan.
Tindak lanjut: Sebelum persetujuan pengadaan relevan', 'Spesifikasi teknis yang mencantumkan kriteria efisiensi energi; evaluasi teknis pemasok; perbandingan konsumsi dan efisiensi peralatan; analisis biaya siklus hidup; persetujuan teknis Tim SMEn atau fungsi terkait; dokumen keputusan pengadaan.', 'Pengadaan; Perencana/Proyek; Operasi/Pemeliharaan; Tim SMEn', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Desain, proyek dan perubahan fasilitas', 'Aspek kinerja energi tidak dinilai sejak tahap konsep, desain, perubahan kapasitas, renovasi atau pengembangan infrastruktur.', 4, 3, 2, 2, true, 'Tetapkan checkpoint review energi pada proyek; libatkan operasi/pemeliharaan sejak awal; klarifikasi peran KINRA, PTPN III/PISMK dan pemilik aset.
Tindak lanjut: Sebelum persetujuan desain dan serah terima', 'Dokumen desain dan spesifikasi yang mempertimbangkan kinerja energi; checklist kajian energi desain; notulen review desain; persetujuan teknis; hasil commissioning dan uji fungsi; daftar temuan serta penyelesaiannya; berita acara serah terima fasilitas.', 'Perencana/Proyek; Pengadaan; Operasi/Pemeliharaan; Tim SMEn; pemilik aset sesuai perjanjian', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Eksternal', 'Risiko', 'Korporasi', 'Batas kendali dan data energi tenant/pihak ketiga', 'Akses data dan pengaruh terhadap konsumsi energi tenant, supplier utilitas, kontraktor atau pengelola aset pihak lain tidak jelas.', 4, 3, 2, 2, true, 'Bedakan energi yang dibeli/dikonsumsi KINRA dari energi yang disalurkan/dikonsumsi tenant; gunakan data terukur dan batas yang terdokumentasi.
Tindak lanjut: Tinjauan kontrak dalam 3 bulan; pembaruan saat perubahan', 'Daftar kontrak dan SLA yang relevan; hasil tinjauan klausul energi dan akses data; peta batas serta tanggung jawab pengelolaan energi; bukti koordinasi dengan tenant, pemasok atau pemilik aset; kontrak yang diperbarui; rekaman pertukaran data energi.', 'Pengelola Kawasan/Utilitas; Legal; Tim SMEn; pemilik kontrak', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Eksternal', 'Risiko', 'Korporasi', 'Ketergantungan pasokan energi dan perubahan tarif', 'Gangguan pasokan listrik/energi atau perubahan tarif/kondisi pasokan memengaruhi layanan fasilitas dan biaya operasi.', 4, 3, 2, 2, true, 'Tetapkan jalur komunikasi supplier, pencatatan gangguan, analisis biaya dan prosedur pemulihan sesuai kewenangan.
Tindak lanjut: Rencana respons dalam 3 bulan; evaluasi saat terjadi perubahan', 'Dokumen rencana respons gangguan pasokan energi; daftar kontak pemasok dan pihak terkait; daftar beban prioritas; prosedur komunikasi dan pemulihan layanan; catatan simulasi atau pengujian; log gangguan aktual; laporan evaluasi dan tindakan pascagangguan.', 'Operasi/Utilitas; Keuangan; Pengelola Kawasan; Tim SMEn', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Eksternal', 'Risiko', 'Korporasi', 'Kepatuhan hukum dan persyaratan kontraktual energi', 'Kewajiban konservasi/manajemen energi, ketenagalistrikan, keselamatan instalasi atau ketentuan kontrak tidak teridentifikasi/terpantau.', 5, 3, 2, 2, true, 'Verifikasi penerapan dan status regulasi terhadap kegiatan/perizinan KINRA; jangan menganggap seluruh regulasi berlaku tanpa pemeriksaan applicability.
Tindak lanjut: Daftar diperbarui dalam 1 bulan; evaluasi sesuai kalender kepatuhan', 'Daftar kewajiban hukum dan persyaratan lainnya yang berlaku; hasil evaluasi kepatuhan; bukti pemenuhan izin atau persyaratan teknis yang relevan; kalender pemenuhan kewajiban; daftar ketidaksesuaian; rencana tindakan koreksi dan bukti penyelesaiannya.', 'Legal/Kepatuhan; pemilik proses; Tim SMEn; Manajemen', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Kompetensi dan kesadaran personel', 'Personel yang memengaruhi kinerja energi belum memahami SOP, set point, pencatatan, pelaporan penyimpangan atau perannya.', 3, 3, 2, 2, true, 'Identifikasi peran yang berdampak pada energi; tetapkan kebutuhan kompetensi, bukti pelatihan dan metode evaluasi.
Tindak lanjut: Pemetaan kompetensi dalam 2 bulan; pelatihan sesuai program', 'Matriks kompetensi personel; identifikasi kebutuhan pelatihan; program dan materi pelatihan SMEn; daftar hadir; hasil evaluasi pemahaman; catatan observasi penerapan SOP; evaluasi efektivitas pelatihan dan tindak lanjut kesenjangan kompetensi.', 'SDM; Tim SMEn; pemilik proses; pengelola kontraktor', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Pemantauan EnPI, EnB dan pencapaian target', 'EnPI/EnB tidak ditinjau saat ada perubahan variabel relevan, fasilitas, jam operasi atau ketersediaan data; penyimpangan tidak ditindaklanjuti.', 4, 3, 2, 2, true, 'Dokumentasikan basis data, metode normalisasi jika diperlukan, pemilik data, batas kontrol dan tata cara perubahan EnB.
Tindak lanjut: Metode disahkan sebelum pelaporan kinerja; review bulanan', 'Dokumen metodologi EnPI dan EnB yang disahkan; daftar indikator dan pemilik data; data konsumsi serta variabel relevan; perhitungan dan grafik tren EnPI; laporan pencapaian target bulanan; catatan investigasi penyimpangan; persetujuan perubahan baseline jika diperlukan.', 'Tim SMEn; Operasi; Keuangan; pemilik EnPI', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Ketersediaan anggaran dan prioritas investasi energi', 'Program efisiensi, pengukuran atau pemeliharaan tertunda karena keterbatasan anggaran, manfaat tidak dihitung atau persetujuan lintas pihak terlambat.', 4, 3, 2, 2, true, 'Buat daftar proyek berperingkat, estimasi biaya/manfaat, tanggung jawab pendanaan dan jalur persetujuan sesuai kepemilikan aset.
Tindak lanjut: Masuk siklus anggaran terdekat; review triwulanan', 'Daftar program peningkatan kinerja energi; proposal dan analisis biaya-manfaat; estimasi penghematan energi; dokumen pengajuan dan persetujuan anggaran; notulen evaluasi triwulanan; status realisasi investasi; laporan manfaat dan verifikasi penghematan.', 'Direksi/Manajemen; Keuangan; Pengadaan/Proyek; Tim SMEn; pemilik aset sesuai perjanjian', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Perubahan organisasi, proses bisnis dan kontrak', 'Perubahan struktur, pembagian kewenangan, proses bisnis, kontrak, fasilitas atau operasi tidak diikuti penilaian dampak terhadap EnMS.', 4, 3, 2, 2, true, 'Wajibkan kajian SMEn sebelum perubahan signifikan disetujui/diterapkan; tetapkan pihak yang menilai dan menyetujui.
Tindak lanjut: Sebelum perubahan diberlakukan', 'Formulir manajemen perubahan; hasil kajian dampak terhadap penggunaan energi, risiko, SEU, EnPI, EnB dan target; persetujuan pihak berwenang; revisi SOP atau dokumen terkait; bukti komunikasi kepada personel; catatan implementasi dan verifikasi pascaperubahan.', 'Manajemen Puncak; pemilik perubahan; Legal; Tim SMEn; pemilik proses', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Korporasi', 'Kesiapan pemulihan dan kontinuitas layanan', 'Respons terhadap gangguan utilitas/peralatan penting belum mempertimbangkan beban prioritas, komunikasi, keselamatan, dan pemulihan layanan.', 4, 3, 2, 2, true, 'Tentukan peran dan batas kewenangan KINRA versus pemilik aset/supplier; jangan mengasumsikan kendali atas fasilitas di luar kewenangan.
Tindak lanjut: Rencana dan kontak diperbarui dalam 3 bulan', 'Dokumen rencana respons dan pemulihan layanan; daftar kontak pemasok, pengelola fasilitas dan pemilik aset; daftar tanggung jawab serta jalur eskalasi; hasil pengujian kesiapan; log gangguan dan waktu pemulihan; laporan evaluasi setelah kejadian.', 'Operasi/Utilitas; Pengelola Fasilitas; supplier/pemilik aset sesuai perjanjian; Tim SMEn', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Peluang', 'Korporasi', 'Peluang optimasi pencahayaan dan tata udara', 'Pola pencahayaan dan tata udara dapat dioptimalkan sesuai okupansi, jadwal, zonasi, kebutuhan layanan dan kenyamanan.', 3, 4, 2, 2, true, 'Tetapkan proyek prioritas berdasarkan data; estimasi penghematan, biaya, risiko kenyamanan dan masa pengembalian.
Tindak lanjut: Pilot dalam 3–6 bulan sesuai persetujuan', 'Dokumen rencana uji coba; data konsumsi sebelum dan sesudah implementasi; catatan jam operasi, setelan dan kondisi relevan; perhitungan penghematan energi; perbandingan terhadap EnB/EnPI; hasil evaluasi kenyamanan atau mutu layanan; keputusan perluasan program.', 'Pengelola Gedung/Fasilitas; Tim SMEn; Keuangan; Pengadaan', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Peluang', 'Korporasi', 'Peluang optimasi pompa dan sistem utilitas', 'Pola operasi, beban, kondisi pompa, kebocoran atau kontrol utilitas berpotensi dioptimalkan.', 3, 3, 2, 2, true, 'Identifikasi sistem prioritas berdasarkan konsumsi, jam operasi dan keluhan; libatkan pemilik aset/supplier bila bukan aset KINRA.
Tindak lanjut: Kajian awal dalam 3 bulan; tindakan sesuai prioritas', 'Laporan kajian pompa dan utilitas; daftar peralatan serta jam operasi; hasil inspeksi dan pemeliharaan; data konsumsi energi; catatan kondisi operasi dan parameter layanan; daftar peluang perbaikan berprioritas; rencana tindakan; hasil pengukuran sebelum dan sesudah perbaikan.', 'Operasi/Utilitas; Pemeliharaan; Tim SMEn; pemilik aset terkait', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Peluang', 'Korporasi', 'Peluang digitalisasi dashboard energi', 'Data meter, tagihan, jam operasi dan indikator dapat dikonsolidasikan untuk mempercepat deteksi penyimpangan dan keputusan.', 3, 3, 2, 2, true, 'Mulai dengan dashboard sederhana yang memiliki sumber data tervalidasi; lindungi akses dan jejak perubahan.
Tindak lanjut: Desain kebutuhan 2 bulan; implementasi bertahap', 'Dokumen kebutuhan dashboard; daftar sumber dan pemilik data; definisi EnPI dan aturan validasi; rancangan dashboard; hasil pengujian dan rekonsiliasi dengan data sumber; log kesalahan dan koreksi; laporan waktu penyusunan data; bukti tindak lanjut atas anomali yang terdeteksi.', 'Tim SMEn; TI; Keuangan; Operasi', 'Dalam 12 bulan sejak rencana disetujui; pemantauan bulanan berikutnya sesuai program EnMS.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Korporasi'),
('Internal', 'Risiko', 'Akuntansi & Keuangan', 'Perencanaan dan pengendalian anggaran energi', 'Penyusunan, persetujuan, dan evaluasi anggaran belum konsisten mengintegrasikan sasaran dan program SMEn.', 4, 3, 2, 2, true, 'Review anggaran energi bersama Tim SMEn, daftar program energi, dan analisis biaya-manfaat.
Tindak lanjut: Integrasikan target energi dalam rencana anggaran; dokumentasikan program yang ditunda beserta pengendalian sementara.', 'RKAP yang mencantumkan sasaran energi; daftar anggaran program SMEn; analisis biaya-manfaat; persetujuan anggaran; laporan realisasi dan deviasi; notulen review triwulan.', 'Penanggung jawab Akuntansi dan Keuangan; Tim SMEn; pemilik proses; Manajemen sesuai kewenangan.', 'Integrasi dalam siklus anggaran tahunan; review triwulanan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Akuntansi & Keuangan'),
('Internal', 'Risiko', 'Akuntansi & Keuangan', 'Analisis biaya energi dan evaluasi kinerja', 'Evaluasi biaya belum konsisten dikaitkan dengan konsumsi, EnPI, baseline energi (EnB), dan target SMEn.', 4, 3, 2, 2, true, 'Format laporan biaya dan konsumsi, review bersama Tim SMEn, dan metodologi analisis terdokumentasi.
Tindak lanjut: Analisis kWh dan rupiah setiap bulan; pisahkan pengaruh tarif dan konsumsi; investigasi varians material.', 'Laporan analisis biaya dan kWh; tren tarif; perhitungan varians; grafik EnPI/EnB; catatan investigasi; notulen review; daftar tindakan dan statusnya.', 'Akuntansi dan Keuangan; Tim SMEn; pemilik EnPI; Pengelola Fasilitas.', 'Metode disepakati sebelum pelaporan berikutnya; review bulanan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Akuntansi & Keuangan'),
('Internal', 'Risiko', 'Akuntansi & Keuangan', 'Pemahaman dan kesadaran ISO 50001:2018', 'Personel keuangan belum sepenuhnya memahami perannya dalam kebijakan energi, sasaran energi, kualitas data, dan peningkatan kinerja energi.', 3, 4, 2, 2, true, 'Materi kesadaran SMEn, matriks kompetensi, panduan kerja, dan penetapan PIC.
Tindak lanjut: Laksanakan pelatihan peran keuangan dalam ISO 50001; evaluasi pemahaman melalui kuis, studi kasus, dan pemeriksaan hasil kerja.', 'Matriks kompetensi; materi ISO 50001 dan peran keuangan; daftar hadir; hasil kuis/studi kasus; bukti komunikasi kebijakan energi; hasil sampling rekonsiliasi dan laporan; catatan tindak lanjut.', 'Penanggung jawab Akuntansi dan Keuangan; SDM; Tim SMEn', 'Pemetaan kebutuhan dalam 1 bulan; pelatihan awal dalam 2 bulan; penyegaran sesuai kebutuhan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Akuntansi & Keuangan'),
('Internal', 'Risiko', 'Akuntansi & Keuangan', 'Penilaian finansial pengadaan dan investasi efisiensi energi', 'Evaluasi investasi belum konsisten mempertimbangkan konsumsi energi selama umur aset dan biaya siklus hidup.', 3, 4, 2, 2, true, 'Tindak lanjut: Wajibkan pertimbangan efisiensi energi untuk pengadaan relevan dan verifikasi manfaat setelah peralatan beroperasi.', 'Business case; analisis biaya siklus hidup; perbandingan spesifikasi dan efisiensi; persetujuan investasi; dokumen pengadaan; data konsumsi sebelum-sesudah; laporan verifikasi penghematan.', 'Akuntansi dan Keuangan; Pengadaan; pemilik teknis/fasilitas; Tim SMEn; pemberi persetujuan investasi.', 'Sebelum persetujuan investasi/pengadaan; evaluasi manfaat 3–6 bulan setelah operasi.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Akuntansi & Keuangan'),
('Internal', 'Risiko', 'Satuan Pengawas Internal (SPI)', 'Audit internal penerapan Sistem Manajemen Energi (SMEn)', 'Pelaksanaan fungsi assurance independen SPI atas kecukupan dan efektivitas tata kelola, manajemen risiko, serta pengendalian Sistem Manajemen Energi (SMEn) berdasarkan ISO 50001:2018. SPI menilai apakah Bagian Sistem Manajemen menjalankan peran pemantauan, evaluasi, dan pelaporan ketidaksesuaian secara memadai, serta apakah risiko signifikan terhadap perusahaan telah diidentifikasi dan ditangani. SPI tidak mengambil alih pengelolaan SMEn maupun pemantauan operasional temuan ISO.', 4, 3, 2, 4, true, 'Program audit berbasis risiko; penetapan ruang lingkup dan kriteria yang jelas; pemeriksaan independen atas kecukupan pemantauan dan tindak lanjut oleh Bagian Sistem Manajemen; review mutu kertas kerja dan laporan; deklarasi independensi auditor; serta mekanisme eskalasi kepada manajemen untuk risiko/temuan signifikan. SPI tidak menjalankan pemantauan teknis temuan ISO.
Tindak lanjut: Melakukan review mutu dan evaluasi pasca-audit; menindaklanjuti rekomendasi hasil audit SPI melalui mekanisme tindak lanjut hasil audit; mengeskalasi temuan kritikal/mayor atau risiko yang belum ditangani; dan menyesuaikan rencana audit berdasarkan hasil evaluasi. Tidak melakukan pemantauan teknis harian atas temuan ISO.', 'Program dan jadwal audit; kriteria dan checklist; surat tugas serta deklarasi independensi; kertas kerja dan bukti audit; laporan audit; hasil review mutu; rekomendasi dan bukti eskalasi; serta hasil evaluasi pasca-audit.', 'Kepala SPI; Ketua/Koordinator Auditor Internal SMEn; auditor internal yang ditugaskan. Bagian Sistem Manajemen merupakan auditee/pemilik proses pemantauan SMEn, bukan pelaksana tugas SPI.', 'Program audit ditetapkan setiap tahun; pelaksanaan sesuai jadwal audit SMEn; evaluasi setelah setiap penugasan dan pada akhir tahun.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Satuan Pengawas Internal (SPI)'),
('Internal', 'Risiko', 'Satuan Pengawas Internal (SPI)', 'Kompetensi, objektivitas, dan independensi auditor internal SMEn', 'Pengelolaan penugasan dan kompetensi personel SPI agar mampu melakukan evaluasi yang objektif terhadap penerapan SMEn, termasuk pemahaman Kebijakan Energi, persyaratan ISO 50001:2018, data konsumsi energi, EnPI, EnB, penggunaan energi signifikan, dan pengendalian operasional.', 4, 3, 2, 4, true, 'Menyusun dan memutakhirkan matriks kompetensi audit SMEn; memberikan pelatihan/pembekalan; mengevaluasi pemahaman auditor; memverifikasi independensi sebelum penugasan; melakukan review silang atas kertas kerja dan laporan; menyediakan auditor pendamping/narasumber teknis bila diperlukan.
Tindak lanjut: Kepala SPI; Ketua/Koordinator Auditor Internal SMEn; Bagian SDM untuk dukungan pelatihan; Koordinator/Tim SMEn sebagai narasumber teknis.', 'Matriks kompetensi, sertifikat pelatihan, daftar hadir, hasil evaluasi kompetensi, surat tugas, deklarasi independensi, dan hasil evaluasi kinerja auditor.', 'Sebelum penugasan audit 2026; evaluasi kompetensi minimal setiap tahun dan setiap terjadi perubahan persyaratan atau penugasan.', 'Matriks kompetensi; sertifikat/rekaman pelatihan; hasil evaluasi; surat tugas; deklarasi independensi; kertas kerja; hasil review; daftar auditor yang memenuhi kualifikasi.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Satuan Pengawas Internal (SPI)'),
('Internal', 'Risiko', 'Satuan Pengawas Internal (SPI)', 'Pemantauan tindak lanjut temuan audit dan verifikasi efektivitas tindakan korektif', 'Pengawasan independen SPI atas kecukupan dan efektivitas mekanisme yang dijalankan Bagian Sistem Manajemen dalam memantau penyelesaian ketidaksesuaian/temuan ISO 50001:2018. SPI menilai apakah analisis akar penyebab, rencana tindakan, tenggat, bukti penyelesaian, dan evaluasi efektivitas telah dikelola secara memadai oleh pemilik proses. Pemantauan teknis dan operasional sehari-hari tetap menjadi tanggung jawab Bagian Sistem Manajemen dan unit terkait.', 4, 3, 2, 4, true, 'Bagian Sistem Manajemen mengelola register temuan, PIC, tenggat, analisis akar penyebab, bukti tindakan, dan pemantauan berkala. SPI secara independen menguji kecukupan mekanisme tersebut melalui audit berbasis risiko, menilai temuan terlambat/berulang, serta mengeskalasi kelemahan signifikan kepada manajemen. Pemisahan peran dan independensi auditor dijaga.
Tindak lanjut: Melaksanakan tindak lanjut atas rekomendasi hasil audit SPI melalui mekanisme pemantauan hasil audit; menguji kembali secara independen sesuai kebutuhan atau penugasan; dan mengeskalasi kondisi yang belum memadai kepada manajemen. Bagian Sistem Manajemen tetap bertanggung jawab atas pemantauan teknis dan penyelesaian temuan ISO.', 'Register temuan yang dikelola Bagian Sistem Manajemen; analisis akar penyebab dan rencana tindakan; bukti implementasi dan evaluasi efektivitas; hasil pengujian sampel SPI; kertas kerja dan laporan audit; serta bukti rekomendasi dan eskalasi kepada manajemen.', 'Bagian Sistem Manajemen dan unit terkait: pemilik proses serta penanggung jawab pemantauan dan tindakan korektif. Kepala SPI/Koordinator Auditor/Auditor: penilaian dan pengujian independen dalam penugasan audit, bukan pemantauan operasional.', 'Pemantauan operasional oleh Bagian Sistem Manajemen sesuai prosedur dan tenggat setiap temuan. SPI melakukan pengujian dalam jadwal audit atau penugasan berbasis risiko; eskalasi dilakukan segera apabila risiko kritikal/mayor teridentifikasi.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Satuan Pengawas Internal (SPI)'),
('Internal', 'Risiko', 'Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan', 'Pengelolaan komunikasi perusahaan dan informasi SMEn', 'Pengelolaan komunikasi internal dan eksternal terkait kebijakan, kinerja, program, serta informasi Sistem Manajemen Energi KINRA kepada karyawan, tenant, mitra usaha, pemerintah, dan pihak berkepentingan lainnya sesuai kewenangan Sekretariat Perusahaan.', 4, 3, 2, 2, true, 'Prosedur komunikasi; Kebijakan Energi yang disahkan; kanal komunikasi resmi; koordinasi dengan Koordinator/Tim SMEn; persetujuan/verifikasi materi oleh unit berwenang; pengendalian surat, publikasi, dan rekaman komunikasi.
Tindak lanjut: Evaluasi efektivitas komunikasi SMEn, perbarui matriks komunikasi, tindak lanjuti masukan, dan pastikan informasi energi diverifikasi sebelum disampaikan kepada pihak berkepentingan.', 'Matriks komunikasi, materi sosialisasi, daftar hadir, notulen, bukti publikasi, umpan balik, log tindak lanjut, serta laporan evaluasi efektivitas komunikasi SMEn.', 'Kepala Bagian Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial; PIC Komunikasi; Koordinator/Tim SMEn.', 'Matriks komunikasi diperbarui maksimal satu bulan; sosialisasi sesuai jadwal; masukan ditindaklanjuti maksimal sepuluh hari kerja; evaluasi efektivitas dilakukan setiap semester.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan'),
('Eksternal', 'Risiko', 'Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan', 'Pemantauan kepatuhan hukum dan kewajiban terkait energi', 'Identifikasi, pemutakhiran, komunikasi, dan pemantauan pemenuhan peraturan perundang-undangan serta kewajiban lain yang relevan dengan penggunaan energi dan penerapan SMEn dalam kegiatan KINRA, sesuai fungsi hukum dan sekretariat perusahaan.', 4, 3, 2, 2, true, 'Daftar peraturan dan kewajiban lain; mekanisme pemantauan perubahan regulasi; koordinasi dengan unit teknis/Tim SMEn; penetapan PIC pemenuhan; penyimpanan bukti kepatuhan; evaluasi kepatuhan sesuai prosedur KINRA.
Tindak lanjut: Perbarui daftar regulasi, verifikasi pemenuhan bersama unit terkait, komunikasikan perubahan, catat kesenjangan, dan pantau penyelesaian tindakan korektif sampai bukti tersedia.', 'Daftar regulasi, hasil telaah perubahan, matriks kewajiban dan PIC, bukti pemenuhan, checklist evaluasi kepatuhan, temuan, serta rekaman tindakan korektif terkait.', 'Kepala Bagian Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial; PIC Hukum; PIC unit teknis; Koordinator/Tim SMEn.', 'Daftar regulasi ditinjau setiap enam bulan; perubahan dikomunikasikan maksimal sepuluh hari kerja; evaluasi kepatuhan minimal setahun sekali dan terdokumentasi secara konsisten.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan'),
('Internal', 'Risiko', 'Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan', 'Pengelolaan program Tanggung Jawab Sosial Perusahaan (TJSL) terkait energi dan lingkungan', 'Perencanaan, koordinasi, pelaksanaan, dan evaluasi program tanggung jawab sosial perusahaan yang relevan dengan pengelolaan kawasan, kepedulian lingkungan, efisiensi energi, serta komunikasi dan pelibatan masyarakat/pihak berkepentingan sesuai program KINRA.', 3, 3, 2, 2, true, 'Perencanaan dan persetujuan program TJSL; prosedur pengelolaan kegiatan; koordinasi dengan unit teknis; anggaran dan jadwal kegiatan; dokumentasi pelaksanaan; evaluasi dan pelaporan hasil program.
Tindak lanjut: Integrasikan efisiensi energi dalam program TJSL relevan, tetapkan indikator, koordinasikan materi edukasi, optimalkan sumber daya, dan evaluasi hasil setiap kegiatan.', 'Rencana dan anggaran TJSL, indikator program, materi edukasi, daftar hadir, dokumentasi, catatan sumber daya, laporan pelaksanaan, serta hasil evaluasi kegiatan.', 'Kepala Bagian Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial; PIC TJSL; unit teknis terkait; Koordinator/Tim SMEn.', 'Pertimbangan energi dimasukkan saat perencanaan; indikator disetujui sebelum kegiatan; evaluasi dan laporan diselesaikan maksimal sepuluh hari kerja setelah setiap kegiatan TJSL.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Sekretariat Perusahaan, Hukum & Tanggung Jawab Sosial Perusahaan'),
('Internal', 'Risiko', 'SDM, Umum & Pengadaan', 'Pengelolaan kompetensi dan kesadaran personil SMEn', 'Pengelolaan kompetensi personil yang berpengaruh terhadap kinerja energi dalam penerapan Kebijakan Energi, SOP, dan pengendalian operasional ISO 50001:2018.', 4, 3, 2, 2, true, 'Matriks kompetensi; program pelatihan; Kebijakan Energi; SOP SMEn; prosedur orientasi; rekaman pelatihan dan evaluasi.
Tindak lanjut: Memantau realisasi pelatihan; meninjau hasil evaluasi; memperbarui matriks kompetensi; menindaklanjuti kesenjangan kompetensi.', 'Matriks kompetensi; materi dan daftar hadir pelatihan; hasil evaluasi; rekaman sosialisasi; evaluasi efektivitas pelatihan.', 'Kepala Bagian SDM, Umum & Pengadaan; PIC Sub Urusan SDM/Pelatihan; Koordinator/Tim SMEn.', 'Sepanjang 2026; evaluasi setelah pelatihan dan minimal setiap semester.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · SDM, Umum & Pengadaan'),
('Internal', 'Risiko', 'SDM, Umum & Pengadaan', 'Pengelolaan fasilitas umum dan pemeliharaan sarana-prasarana', 'Pengelolaan dan pemeliharaan gedung, ruang kerja, pencahayaan, tata udara, peralatan kantor, serta fasilitas pendukung yang berada dalam kendali operasional KINRA.', 4, 3, 2, 2, true, 'Jadwal pemeliharaan; checklist inspeksi; SOP penggunaan fasilitas; mekanisme pelaporan kerusakan; koordinasi unit teknis; pencatatan energi.
Tindak lanjut: Memantau jadwal pemeliharaan; mengevaluasi hasil inspeksi dan konsumsi energi; menindaklanjuti kerusakan; memverifikasi efektivitas perbaikan.', 'Daftar inventaris fasilitas; jadwal dan checklist preventive maintenance; laporan inspeksi; work order; catatan kerusakan/perbaikan; log operasi dan konsumsi energi.', 'Kepala Bagian SDM, Umum & Pengadaan; PIC Umum/Fasilitas; PIC pemeliharaan; koordinasi Bagian Mekanikal & Elektrikal/Fasilitas dan Tim SMEn.', 'Inspeksi/pemeliharaan berkala sepanjang 2026; evaluasi bulanan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · SDM, Umum & Pengadaan'),
('Internal', 'Risiko', 'SDM, Umum & Pengadaan', 'Pengadaan barang/jasa dengan mempertimbangkan kinerja energi', 'Perencanaan dan pengadaan peralatan listrik, lampu, AC, perangkat kantor, jasa pemeliharaan, dan kebutuhan fasilitas yang dapat memengaruhi kinerja energi KINRA.', 4, 3, 2, 2, true, 'Prosedur pengadaan; permintaan barang/jasa; spesifikasi teknis; evaluasi pemasok; persetujuan pembelian; pemeriksaan penerimaan; koordinasi unit pengguna/Tim SMEn.
Tindak lanjut: Memantau dokumen pengadaan; mengevaluasi pemasok dan hasil penerimaan; mencatat penyimpangan; memperbarui kriteria berdasarkan evaluasi kinerja peralatan.', 'Daftar pengadaan relevan energi; spesifikasi teknis; evaluasi penawaran/pemasok; persetujuan pembelian; berita acara penerimaan; bukti label efisiensi; evaluasi kesesuaian barang.', 'Kepala Bagian SDM, Umum & Pengadaan; PIC Pengadaan; unit pengguna/PIC teknis; Koordinator/Tim SMEn.', 'Setiap proses pengadaan relevan sepanjang 2026; evaluasi minimal setiap semester.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · SDM, Umum & Pengadaan'),
('Internal', 'Risiko', 'Manajemen Risiko & TI', 'Pengelolaan risiko dan peluang EnMS', 'Pengelolaan identifikasi, analisis, evaluasi, perlakuan, pemantauan, dan peninjauan risiko serta peluang yang dapat memengaruhi pencapaian hasil EnMS KINRA.', 4, 3, 2, 2, true, 'Menetapkan metodologi risiko EnMS; kriteria dampak/kemungkinan; pemilik risiko; jadwal review; mekanisme eskalasi; dan integrasi dengan proses manajemen perubahan.
Tindak lanjut: Review minimal triwulanan dan setiap ada perubahan signifikan; evaluasi keterlambatan tindakan; lakukan pembaruan penilaian dan eskalasi bila skor meningkat.', 'Register risiko/peluang EnMS yang disahkan; metodologi dan kriteria penilaian; daftar pemilik risiko; rencana perlakuan beserta PIC dan tenggat; notulen review triwulanan; bukti pembaruan saat perubahan signifikan; status dan evaluasi efektivitas tindakan.', 'Kepala Bagian Manajemen Risiko & TI; Koordinator/Tim EnMS; pemilik proses terkait.', 'Register awal diselesaikan maksimal 30 hari setelah persetujuan; review triwulanan dan saat perubahan signifikan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Manajemen Risiko & TI'),
('Internal', 'Risiko', 'Manajemen Risiko & TI', 'Pengelolaan data energi dan informasi terdokumentasi EnMS', 'Pengendalian data dan informasi yang digunakan untuk perencanaan, pemantauan, pengukuran, analisis, evaluasi, dan pembuktian penerapan EnMS.', 4, 3, 2, 2, true, 'Menetapkan prosedur pengumpulan, validasi, koreksi, penyimpanan, pencadangan, dan distribusi data; menentukan sumber data resmi dan PIC setiap data.
Tindak lanjut: Memeriksa kelengkapan dan ketepatan waktu data setiap bulan; melakukan sampling konsistensi; menindaklanjuti anomali dan keterlambatan.', 'Daftar sumber data energi dan pemilik data; format pelaporan baku; rekaman meter dan tagihan energi; hasil rekonsiliasi/validasi data; daftar induk dokumen EnMS; riwayat revisi; log akses dan perubahan; laporan kelengkapan serta ketepatan waktu data.', 'Kepala Bagian Manajemen Risiko & TI; PIC data/informasi; pemilik data energi pada unit terkait; Koordinator EnMS.', 'Standar data dan dokumen maksimal 45 hari; pemeriksaan dilakukan bulanan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Manajemen Risiko & TI'),
('Internal', 'Risiko', 'Manajemen Risiko & TI', 'Backup, pemulihan, dan kesinambungan informasi EnMS', 'Perlindungan dan pemulihan data energi, dokumen, serta aplikasi pendukung EnMS saat terjadi kegagalan perangkat, kesalahan pengguna, insiden keamanan, atau gangguan layanan.', 4, 3, 2, 2, true, 'Proses backup yang tersedia (frekuensi, cakupan, retensi, lokasi, dan hasil uji perlu diverifikasi); pengamanan media penyimpanan.
Tindak lanjut: Monitoring hasil backup sesuai jadwal; uji restore minimal semesteran atau sesuai tingkat kritikalitas; evaluasi setelah insiden.', 'Kebijakan/prosedur backup dan pemulihan; daftar data dan sistem yang dicadangkan; jadwal serta log keberhasilan backup; bukti penyimpanan salinan terpisah; ketentuan retensi; hasil uji restore; catatan kegagalan backup; laporan tindakan korektif dan evaluasi pemulihan.', 'Kepala Bagian Manajemen Risiko & TI; PIC Infrastruktur TI; pemilik data EnMS.', 'Kebijakan dan jadwal backup maksimal 30 hari; uji restore pertama maksimal 60 hari; evaluasi berkala sesuai tingkat kritikalitas.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Manajemen Risiko & TI'),
('Internal', 'Risiko', 'Pengembangan', 'Perencanaan pengembangan kawasan dan infrastruktur', 'Perencanaan pengembangan kawasan industri, perluasan area, pembangunan atau peningkatan jalan, drainase, jaringan utilitas, penerangan, gedung, dan fasilitas pendukung yang dapat memengaruhi konsumsi energi dalam kendali atau pengaruh KINRA.', 4, 3, 2, 2, true, 'Persyaratan teknis pengembangan; review masterplan dan studi kelayakan; koordinasi dengan unit operasi, utilitas, Pengadaan, dan Tim EnMS; pertimbangan efisiensi energi dalam desain dan spesifikasi.
Tindak lanjut: Review energi pada setiap usulan proyek; pantau tindak lanjut rekomendasi desain; perbarui penilaian jika lingkup, kapasitas, teknologi, atau kebutuhan fasilitas berubah.', 'Masterplan dan rencana pengembangan; studi kelayakan; checklist kajian energi; estimasi kebutuhan energi; alternatif desain dan evaluasi biaya siklus hidup; notulen review Tim EnMS; persetujuan desain dan tindak lanjut rekomendasi.', 'Bagian Pengembangan / Pengembangan Usaha & Kawasan; Tim EnMS/PIC Energi; unit Teknik/Operasi dan Pengadaan sesuai kewenangan.', 'Checklist kajian energi ditetapkan maksimal 60 hari; diterapkan pada seluruh usulan pengembangan berikutnya.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pengembangan'),
('Internal', 'Risiko', 'Pengembangan', 'Pengembangan desain teknis dan spesifikasi fasilitas', 'Pengembangan konsep, desain, spesifikasi teknis, dan dokumen perencanaan fasilitas kawasan yang meliputi gedung, penerangan, sistem tata udara, pompa, jaringan utilitas, serta peralatan pendukung.', 4, 3, 2, 2, true, 'Review desain oleh unit teknis; persyaratan teknis dalam TOR/spesifikasi; evaluasi alternatif peralatan; koordinasi dengan pengelola gedung/utilitas dan Tim EnMS.
Tindak lanjut: Pemeriksaan pada setiap tahapan desain; verifikasi spesifikasi sebelum tender/pengadaan; evaluasi perubahan desain dan dampaknya terhadap energi.', 'TOR/KAK; gambar dan perhitungan desain; spesifikasi teknis; data efisiensi peralatan; perbandingan alternatif; hasil review desain; checklist persyaratan energi; daftar deviasi dan persetujuannya.', 'Bagian Pengembangan / Pengembangan Usaha & Kawasan; konsultan/perencana; unit Teknik/Operasi; Tim EnMS/PIC Energi; Pengadaan.', 'Checklist desain ditetapkan maksimal 90 hari; review dilakukan pada setiap proyek dan revisi desain.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pengembangan'),
('Internal', 'Risiko', 'Pengembangan', 'Pengendalian pelaksanaan dan perubahan proyek pengembangan', 'Pengendalian proyek pembangunan, peningkatan, atau perubahan fasilitas dan infrastruktur kawasan agar sesuai desain, spesifikasi, dan kebutuhan operasional KINRA.', 4, 3, 2, 2, true, 'Checklist inspeksi berbasis spesifikasi; persetujuan perubahan; pengujian dan commissioning; pemeriksaan dokumen serah terima; koordinasi dengan unit penerima dan Tim EnMS.
Tindak lanjut: Memantau temuan proyek; inspeksi sebelum serah terima; mengevaluasi konsumsi awal setelah fasilitas beroperasi dan membandingkannya dengan estimasi/desain.', 'Dokumen kontrak dan spesifikasi; laporan kemajuan; checklist inspeksi; persetujuan perubahan; data teknis substitusi; hasil testing/commissioning; berita acara serah terima; as-built drawing; manual operasi; catatan pelatihan; data konsumsi energi awal.', 'Bagian Pengembangan / Pengembangan Usaha & Kawasan; Manajer/PIC Proyek; konsultan pengawas; kontraktor; unit Teknik/Operasi; Tim EnMS.', 'Pengendalian selama proyek; verifikasi sebelum serah terima; evaluasi awal maksimal 3 bulan setelah fasilitas beroperasi.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pengembangan'),
('Internal', 'Risiko', 'Pemasaran & Penjualan', 'Administrasi dan aktivitas kerja Bagian Pemasaran & Penjualan', 'Pengelolaan aktivitas administrasi pemasaran dan penjualan yang mencakup penyusunan proposal, penawaran harga, korespondensi, pengolahan data pelanggan, penyusunan laporan penjualan, serta koordinasi internal.', 3, 4, 2, 2, true, 'Pengaturan jam kerja; kebijakan pemadaman perangkat elektronik; pengaturan AC; penggunaan dokumen digital; pemeliharaan peralatan kantor; sosialisasi hemat energi kepada karyawan.
Tindak lanjut: Melaksanakan inspeksi penggunaan energi; mengevaluasi konsumsi listrik bulanan; melakukan sosialisasi berkala; mengidentifikasi penyimpangan dan melaksanakan tindakan korektif.', 'Checklist pemadaman peralatan; daftar inventaris peralatan elektronik; catatan pemeliharaan; laporan penggunaan listrik gedung; dokumentasi sosialisasi; hasil inspeksi energi.', 'Kepala Bagian Pemasaran & Penjualan; seluruh staf Pemasaran & Penjualan; Bagian Umum/GA; PIC Energi/Tim EnMS.', 'Maksimal 2 bulan sejak rencana disetujui; selanjutnya dilakukan setiap hari kerja.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pemasaran & Penjualan'),
('Internal', 'Risiko', 'Pemasaran & Penjualan', 'Pengelolaan informasi dan komunikasi pemasaran secara digital', 'Pengelolaan informasi pemasaran, promosi digital, komunikasi dengan calon tenant dan pelanggan, serta pemanfaatan sistem teknologi informasi untuk mendukung proses pemasaran dan penjualan kawasan industri.', 2, 4, 1, 2, true, 'Penggunaan perangkat TI sesuai kebutuhan; pengaturan mode hemat daya; pemadaman perangkat setelah digunakan; pengaturan penggunaan jaringan dan perangkat komunikasi; rapat daring untuk mengurangi perjalanan yang tidak diperlukan.
Tindak lanjut: Memeriksa penggunaan perangkat TI; mengevaluasi kepatuhan terhadap kebijakan hemat energi; meninjau spesifikasi energi perangkat pada pengadaan atau penggantian.', 'Daftar inventaris perangkat TI; checklist pemadaman; dokumentasi kebijakan penggunaan perangkat; catatan pengadaan; data penggunaan listrik jika tersedia; hasil inspeksi.', 'Kepala Bagian Pemasaran & Penjualan; PIC TI; Bagian Umum/GA; PIC Energi/Tim EnMS.', 'Maksimal 3 bulan sejak rencana disetujui; selanjutnya dipantau secara berkala.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pemasaran & Penjualan'),
('Internal', 'Risiko', 'Pemasaran & Penjualan', 'Pengelolaan data penjualan, evaluasi pasar, dan perencanaan kegiatan pemasaran', 'Pengelolaan data pelanggan, data penjualan lahan, tingkat okupansi kawasan, evaluasi kebutuhan pasar, dan perencanaan strategi pemasaran untuk mendukung pencapaian target bisnis KINRA.', 2, 3, 1, 2, true, 'Penggunaan sistem administrasi dan pelaporan; pengaturan penggunaan komputer dan printer; pengendalian penggunaan ruang rapat; perencanaan anggaran pemasaran; penggunaan dokumen elektronik.
Tindak lanjut: Mengevaluasi penggunaan dokumen digital; memantau konsumsi listrik; mengevaluasi kebutuhan fasilitas rapat; memperbaiki kegiatan yang menunjukkan penggunaan energi tidak efisien.', 'Laporan penjualan; laporan kegiatan pemasaran; dokumen perencanaan anggaran; laporan digital; checklist penggunaan perangkat; data konsumsi listrik; hasil evaluasi berkala.', 'Kepala Bagian Pemasaran & Penjualan; PIC Administrasi Pemasaran; Bagian Umum/GA; PIC Energi/Tim EnMS.', 'Maksimal 3 bulan sejak rencana disetujui; selanjutnya dievaluasi setiap bulan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Pemasaran & Penjualan'),
('Internal', 'Risiko', 'Produksi Kawasan', 'Pengoperasian sistem drainase dan stasiun pompa pengendali genangan', 'Pengelolaan saluran drainase, kolam retensi, sump pit, dan stasiun pompa pengendali genangan apabila fasilitas tersebut berada dalam kendali operasional KINRA.', 3, 3, 2, 2, true, 'Inspeksi saluran; pembersihan rutin; pemeliharaan pompa; pengujian sensor dan panel; prosedur operasi saat hujan; pencatatan gangguan dan jam operasi.
Tindak lanjut: Meninjau catatan operasi saat hujan; mengevaluasi jam operasi pompa; memperbaiki sensor atau pompa yang tidak efisien; memperbarui penilaian saat kapasitas atau konfigurasi berubah.', 'Checklist drainase; log pompa; catatan kWh/BBM; jam operasi; laporan genangan; catatan pembersihan; hasil pengujian sensor; catatan pemeliharaan.', 'Pengelola Produksi Kawasan; Bagian Teknik/Operasional; Petugas Utilitas; PIC Energi/Tim EnMS.', 'Jadwal inspeksi ditetapkan maksimal 1 bulan; pemantauan dilakukan rutin dan sebelum/sesudah hujan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Produksi Kawasan'),
('Internal', 'Risiko', 'Produksi Kawasan', 'Pengoperasian penerangan jalan dan area fasilitas kawasan', 'Pengoperasian dan pemeliharaan penerangan jalan, area terbuka, area parkir, fasilitas umum, serta penerangan pendukung operasional kawasan yang berada dalam kendali KINRA.', 3, 4, 2, 2, true, 'Jadwal nyala dan padam; inspeksi penerangan; pemeliharaan panel dan timer; penggantian lampu rusak; pencatatan titik lampu dan daya terpasang.
Tindak lanjut: Memantau kWh penerangan; melakukan inspeksi malam dan siang; menguji timer/photocell; mengevaluasi tingkat pencahayaan dan melakukan koreksi.', 'Daftar titik lampu dan daya; jadwal operasi; catatan kWh; checklist inspeksi; bukti penggantian LED; catatan pemeliharaan; hasil pengukuran pencahayaan bila ada.', 'Pengelola Produksi Kawasan; Bagian Teknik/Operasional; Petugas Pemeliharaan; PIC Energi/Tim EnMS.', 'Inventarisasi dan evaluasi maksimal 3 bulan; inspeksi rutin sesuai jadwal pemeliharaan.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Produksi Kawasan'),
('Internal', 'Risiko', 'Produksi Kawasan', 'Pengoperasian sistem proteksi kebakaran dan pompa pemadam', 'Pengoperasian dan pemeliharaan fasilitas proteksi kebakaran kawasan, termasuk fire pump, jockey pump, panel kontrol, tangki, hydrant, dan peralatan pendukung yang berada dalam kendali KINRA.', 4, 2, 2, 1, true, 'Prosedur pengujian fire pump; jadwal inspeksi; pemeliharaan pompa; pemeriksaan tekanan dan level tangki; pengendalian akses panel; pencatatan hasil pengujian.
Tindak lanjut: Meninjau log pengujian dan pemeliharaan; mengevaluasi konsumsi selama pengujian; menindaklanjuti kebocoran atau anomali; memastikan tidak ada pengurangan frekuensi uji yang diwajibkan.', 'Log pengujian fire pump; catatan kWh/BBM; hasil uji tekanan; checklist inspeksi; catatan pemeliharaan; laporan gangguan; dokumen persyaratan keselamatan.', 'Pengelola Produksi Kawasan; Petugas K3/Fire & Safety; Bagian Teknik/Operasional; PIC Energi/Tim EnMS.', 'Sesuai jadwal pengujian dan pemeliharaan yang ditetapkan; evaluasi energi minimal setiap bulan atau sesuai program.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Produksi Kawasan'),
('Internal', 'Risiko', 'Mekanikal & Elektrikal, Fasilitas dan Pengamanan', 'Pengoperasian lift, eskalator, dan peralatan mekanikal gedung', 'Pengoperasian dan pemeliharaan lift, eskalator, hoist, pintu otomatis, serta peralatan mekanikal gedung lain yang berada dalam kendali operasional KINRA, apabila tersedia.', 3, 3, 2, 2, true, 'Jadwal inspeksi dan pemeliharaan; pengujian keselamatan; operator/teknisi berwenang; pencatatan gangguan; pengendalian akses dan penggunaan.
Tindak lanjut: Meninjau data penggunaan dan gangguan; mengevaluasi konsumsi jika tersedia; memastikan mode hemat energi tidak mengganggu fungsi keselamatan.', 'Daftar aset; spesifikasi daya; log penggunaan; checklist inspeksi; sertifikat/pengujian keselamatan; WO pemeliharaan; data kWh bila tersedia.', 'Koordinator Mekanikal & Elektrikal; teknisi mekanikal; Pengelola Gedung/Fasilitas; PIC Energi/Tim EnMS.', 'Verifikasi aset maksimal 1 bulan; pemeliharaan sesuai jadwal dan evaluasi berkala.', 'Formulir Risiko 6.1 001/SOP-007/KINRA/SMEn/X/2026 · Mekanikal & Elektrikal, Fasilitas dan Pengamanan'),
('Internal', 'Risiko', 'Mekanikal & Elektrikal, Fasilitas dan Pengamanan', 'Pengoperasian sistem keamanan elektronik dan pengawasan kawasan', 'Pengelolaan CCTV, server/NVR, perangkat jaringan, access control, barrier gate, alarm, perangkat komunikasi, dan sistem keamanan elektronik yang berada dalam kendali KINRA.', 3, 4, 2, 2, true, 'Jadwal pemeliharaan; pembatasan akses ruang perangkat; pemeriksaan UPS; pemantauan fungsi CCTV dan access control; pengaturan monitor; prosedur gangguan keamanan.
